  const name = new Date(`${month}-01T00:00`).toLocaleDateString("ru-RU", { month: "long" });

  return (
    <main className="mx-auto w-full max-w-md p-8">
      <h1 className="text-3xl font-semibold">
        Отчёт за {name} {month.slice(0, 4)}
